<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../api/client'
import type { RequirementSummary } from '../api/contracts'
import StatusBadge from '../components/StatusBadge.vue'
const route = useRoute(), requirements = ref<RequirementSummary[]>([]), selectedRequirementId = ref(''), error = ref(''), loading = ref(true)
const selectedId = computed(() => selectedRequirementId.value || (typeof route.params.taskId === 'string' ? route.params.taskId : requirements.value[0]?.id))
const selected = computed(() => requirements.value.find(item => item.id === selectedId.value) || requirements.value[0])
async function load() { loading.value = true; error.value = ''; try { requirements.value = (await api.requirements()).requirements } catch (e) { error.value = e instanceof Error ? e.message : '无法读取需求列表' } finally { loading.value = false } }
watch(() => route.params.taskId, value => { selectedRequirementId.value = typeof value === 'string' ? value : '' }, { immediate: true })
onMounted(load)
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">REQUIREMENT → RUN → ARTIFACT</p><h1>需求列表</h1><p>显示受保护的需求摘要、当前状态和经验证的运行历史；正文仅在服务端冻结 Plan 中受控使用。</p></div><button class="quiet-button" @click="load">刷新</button></div><p v-if="error" class="data-warning">⚠ {{ error }}</p><div class="requirement-layout"><section class="requirement-list"><p v-if="loading" class="empty-state">正在读取需求与关联 Run…</p><p v-else-if="!requirements.length" class="empty-state">当前没有保存的需求。</p><RouterLink v-for="item in requirements" :key="item.id" :to="`/requirements/${item.id}`" class="requirement-card" :class="{ selected: item.id === selected?.id }" @click="selectedRequirementId = item.id"><span>{{ item.id }} · P{{ item.priority }}</span><b>{{ item.title }}</b><small>{{ item.status }} · {{ item.runs.length }} 个关联 Run</small></RouterLink></section><article v-if="selected" class="requirement-detail"><p class="eyebrow">{{ selected.id }} · {{ selected.status }}</p><h2>{{ selected.title }}</h2><p class="description">{{ selected.description || '该需求没有可展示的正文。' }}</p><div class="requirement-actions"><RouterLink v-if="selected.pending" class="quiet-button" :to="`/plans?profile=${encodeURIComponent(selected.profile_id)}&task=${encodeURIComponent(selected.id)}`">进入受控执行</RouterLink><span v-else class="status passed">已完成或已归档</span></div><section class="run-history"><h3>关联运行（{{ selected.runs.length }}）</h3><p v-if="!selected.runs.length" class="empty-state">尚未记录关联 Run。</p><article v-for="run in selected.runs" :key="run.run_id" class="history-row"><div><StatusBadge :status="run.status"/><b>{{ run.run_id }}</b><small>{{ run.last_occurred_at }} · {{ run.event_count }} events</small></div><div><RouterLink class="quiet-button" :to="`/runs/${run.run_id}`">查看运行</RouterLink><a v-if="run.artifact?.preview_url" class="primary-button" :href="run.artifact.preview_url" target="_blank" rel="noopener">预览产物</a></div></article></section></article></div></section></template>
<style scoped>.requirement-layout{display:grid;grid-template-columns:minmax(230px,.8fr) minmax(0,2fr);gap:16px}.requirement-list{display:grid;align-content:start;gap:8px}.requirement-card{display:grid;gap:5px;padding:13px;border:1px solid var(--line);border-radius:10px;background:var(--panel);color:inherit;text-decoration:none}.requirement-card.selected{border-color:var(--accent)}.requirement-card span,.requirement-card small{color:var(--muted);font-size:11px}.requirement-card b{font-size:14px}.requirement-detail{min-width:0;padding:18px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}.requirement-detail h2{margin:0 0 12px}.description{white-space:pre-wrap;line-height:1.7;color:var(--muted)}.requirement-actions{margin:16px 0}.run-history{margin-top:20px}.run-history h3{font-size:14px}.history-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 0;border-top:1px solid var(--line)}.history-row>div{display:grid;gap:4px}.history-row>div:last-child{display:flex;gap:8px}.history-row small{color:var(--muted);font-size:11px}@media(max-width:760px){.requirement-layout{grid-template-columns:1fr}.history-row{align-items:flex-start;flex-direction:column}}</style>
